-- FX schema; a comment mentioning UNIQUE (nothing) must not parse
CREATE TABLE FX_WIDGET (
    WIDGET_PK   BIGSERIAL PRIMARY KEY,
    CODE        VARCHAR(20) NOT NULL,
    NAME_EN     VARCHAR(150),
    PARENT_ID   BIGINT,
    IS_PRIMARY_FL NUMERIC(1) NOT NULL DEFAULT 0
);
ALTER TABLE FX_WIDGET ADD CONSTRAINT UQ_FX_WIDGET_CODE UNIQUE (code);
ALTER TABLE FX_WIDGET ADD CONSTRAINT UQ_FX_WIDGET_NAME UNIQUE (name_en);   -- entity says NAME
ALTER TABLE FX_WIDGET ADD CONSTRAINT UQ_FX_WIDGET_TMP  UNIQUE (parent_id, code);
CREATE TABLE FX_LEGACY (
    ID BIGINT PRIMARY KEY,
    TOKEN VARCHAR(64),
    CONSTRAINT UQ_FX_LEGACY_TOKEN UNIQUE (TOKEN)
);
CREATE TABLE OTHER_MODULE_TABLE (ID BIGINT PRIMARY KEY, K VARCHAR(10));
ALTER TABLE OTHER_MODULE_TABLE ADD CONSTRAINT UQ_OTHER_K UNIQUE (K);
